675|# every other engine). Right before the start the engine's launch invariant is read afresh
676|# (Get-EngineLaunchBlock -Fresh, D4 - muse: the billing guard re-reads auth.json and the
677|# environment, never a sign-in cached by the preflight minutes earlier) and, for an engine other
678|# than codex, the %-hazard of a .cmd launcher (F02-14); a refusal starts nothing. { Proc ($null
679|# when nothing was started); Refusal ('' or why the launch was refused); Error ('' or why
680|# Start-Process failed) }. Reads the run's $engineName and $repoRoot.
681|function Start-EngineProcess {
682|    param([string]$Launcher, [string[]]$Argv, [string]$StdoutPath, [string]$StderrPath, [string]$StdinPath)
683|    $r = [pscustomobject]@{ Proc = $null; Refusal = ''; Error = '' }
684|    $refusal = Get-EngineLaunchBlock -Engine $engineName -Fresh
685|    if (-not $refusal -and $engineName -ne 'codex') { $refusal = Get-CmdArgvHazard -Launcher $Launcher -Argv $Argv }
686|    if ($refusal) { $r.Refusal = [string]$refusal; return $r }
687|    try {
688|        $r.Proc = Start-Process -FilePath $Launcher -ArgumentList ((($Argv | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')) `
689|            -WorkingDirectory $repoRoot -NoNewWindow -PassThru `
690|            -RedirectStandardOutput $StdoutPath `
691|            -RedirectStandardError $StderrPath `
692|            -RedirectStandardInput $StdinPath
693|    } catch {
694|        $r.Error = ConvertTo-OneLine $_.Exception.Message
695|    }
696|    return $r
697|}
