699|# One more turn (an engine's denial retry and format repair; wave 24: the timeout continuation
700|# of every engine, codex included) under the SAME task lock and recovery record as the run: the
701|# record goes launching -> running (child pid, start time, `events` = this turn's event stream)
702|# before the process is waited on; a timeout kills the process tree, and survivors are recorded
703|# (state survivors) and keep the record.
704|# -PromptPath / -PromptText (wave 23, D1): the turn's own prompt file, written first (muse
705|# names it in its argv; its stdin is then empty). Right before the start (Start-EngineProcess)
706|# the engine's launch invariant (D4; read afresh - wave 24, F15-1) and, for an engine other than
707|# codex, the .cmd %-hazard (F02-14) are checked again: a refusal starts nothing (the record gets
708|# its previous state back).
709|# Reads the run's $pendingRecord, $pendingPath, $engineLauncher, $engineName and $repoRoot.
710|# { Exit (-1 unless it exited); Problem ('' or why the turn did not complete); Wall;
711|# KeepPending; Stderr (UTF-8 text); Started (a process was started: one more engine turn -
712|# for muse one more subscription prompt) }.
713|function Invoke-EngineTurn {
714|    param([string[]]$Argv, [string]$StdinText, [string]$EventsPath, [string]$StdinPath, [string]$StderrPath, [int]$Timeout, [string]$Note, [string]$PromptPath = '', [string]$PromptText = '')
715|    $t = [pscustomobject]@{ Exit = -1; Problem = ''; Wall = 0; KeepPending = $false; Stderr = ''; Started = $false }
716|    if ($PromptPath) { Write-Utf8NoBom -Path $PromptPath -Text $PromptText }
717|    Write-Utf8NoBom -Path $StdinPath -Text $StdinText
718|    $watch = [System.Diagnostics.Stopwatch]::StartNew()
719|    $prevState = [string]$pendingRecord.state
720|    $prevNote = [string]$pendingRecord.note
721|    $pendingRecord.state = 'launching'
722|    $pendingRecord.note = "$Note being started; its pid is not recorded yet"
723|    try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch {
724|        $t.Problem = "could not write the recovery record ($(ConvertTo-OneLine $_.Exception.Message)); the turn was not started"
725|        return $t
726|    }
727|    $launch = Start-EngineProcess -Launcher $engineLauncher -Argv $Argv -StdoutPath $EventsPath -StderrPath $StderrPath -StdinPath $StdinPath
728|    if ($launch.Refusal) {
729|        $t.Problem = "refused before launch: $($launch.Refusal)"
730|        $pendingRecord.state = $prevState
731|        $pendingRecord.note = $prevNote
732|        try { Write-PendingFile -Path $pendingPath -Record $pendingRecord } catch { }
733|        return $t
734|    }
735|    $proc = $launch.Proc
736|    if ($launch.Error) { $t.Problem = "could not start $engineName - $($launch.Error)" }
737|    if ($proc) {
738|        if ($script:LegacyPS) { try { $null = $proc.Handle } catch { } }
739|        $t.Started = $true
740|        $registered = $true
741|        try {
742|            $pendingRecord.state = 'running'
743|            $pendingRecord.child_pid = $proc.Id
744|            $pendingRecord.child_start_time = [string](Get-ProcessStartIso -ProcessId $proc.Id)
745|            $pendingRecord.note = $Note
746|            $evRel = Get-RepoRelativePath -Root $repoRoot -Path $EventsPath
747|            $pendingRecord.events = $(if ($evRel) { $evRel } else { $EventsPath })
748|            Write-PendingFile -Path $pendingPath -Record $pendingRecord
749|        } catch {
750|            $registered = $false
751|            $t.Problem = "could not register the $Note process ($(ConvertTo-OneLine $_.Exception.Message)); it was stopped"
752|            # the record on disk still says launching: so does the one in memory
753|            $pendingRecord.state = 'launching'; $pendingRecord.child_pid = $null; $pendingRecord.child_start_time = ''
754|            $null = Stop-ProcessTree -Process $proc
755|        }
756|        if ($registered) {
757|            if (-not $proc.WaitForExit($Timeout * 1000)) {
758|                $surv = Stop-ProcessTree -Process $proc   # [int[]]; never wrap in @()
759|                $t.Problem = "timeout after $Timeout s (process tree killed)"
760|                if ($surv.Count -gt 0) {
761|                    $t.Problem = "timeout after $Timeout s (process tree killed; $($surv.Count) processes survived: pid $($surv -join ', '))"
762|                    $t.KeepPending = $true
763|                    try {
764|                        $pendingRecord.state = 'survivors'
765|                        $pendingRecord.survivors = [object[]]@(New-SurvivorEntries -Pids $surv)
766|                        Write-PendingFile -Path $pendingPath -Record $pendingRecord
767|                    } catch { }
768|                }
769|            } else {
770|                $t.Exit = $proc.ExitCode
771|            }
772|        }
773|    }
774|    $watch.Stop()
775|    $t.Wall = [math]::Round($watch.Elapsed.TotalSeconds, 1)
776|    $t.Stderr = Read-SharedText -Path $StderrPath
777|    return $t
778|}
