3021|    # ------------------------------------------------------------------------- timeout continuation
3022|
3023|    # (wave 24, T1 - the maintainer's request: the provider and the CLI still hold the
3024|    # conversation; Codex keeps the whole rollout of a thread the bridge killed) The MAIN turn
3025|    # was killed on its timeout: ONE more turn on that thread - the main turn's options, codex
3026|    # `exec ... resume <thread>`, agy --conversation, muse --session-id - asks the reviewer to
3027|    # finish now instead of starting over, within -ContinueSec s, under the same lock and
3028|    # recovery record (Invoke-EngineTurn). Not when the thread is unknown, processes survived
3029|    # the kill, files changed during the run (wave 24b, F08-2: ONE tree check for every engine -
3030|    # codex's fingerprints too), the killed turn's own evidence names a quota, billing or auth
3031|    # failure (F08-3: every candidate through the one classifier, Get-KilledTurnFailure), or
3032|    # -ContinueSec is 0 (ledger timeout_continue.outcome "not attempted: <why>"); the launch
3033|    # guard (muse: billing) is read afresh right before it. A prompt-only transport gets the reply
3034|    # format and the schema again (F07-1). The continuation counts only when its reply passes the
3035|    # checks of a first reply (F08-5, Test-ContinuationReply) - then it is ingested exactly like
3036|    # one ("usable reply (after a timeout continuation)"); otherwise the salvage below covers both
3037|    # turns' streams, and a continuation that FAILED supplies the provider failure (F08-4). At
3038|    # most once.
3039|    $timeoutContinueRecord = $null
3040|    $continued = $false
3041|    $continueTurn = $null
3042|    $continueThread = ''
3043|    $continueProblem = ''
3044|    # (wave 24b) the continuation answered, but not with a usable reply (F08-5); the evidence of a
3045|    # continuation that failed - { Texts; Class } for provider_failure (F08-4)
3046|    $continueRejected = $false
3047|    $continueFailure = $null
3048|    $continueEventsRel = $null
3049|    $continueEventsName = "$nn-$enginePrefix-$ReplyName.continue.events.jsonl"
3050|    $continueEventsPath = Join-Path $handoffsDir $continueEventsName
3051|    if ($mainTimedOut) {
3052|        $continueThread = $(if ($threadId) { $threadId } elseif (-not $isCodex -and $agyTurn) { [string]$agyTurn.ThreadCandidate } else { '' })
3053|        $continueSkip = ''
3054|        if ($ContinueSec -le 0) { $continueSkip = '-ContinueSec 0' }
3055|        elseif (-not $continueThread) { $continueSkip = 'the thread of the killed turn is not known' }
3056|        elseif ($mainSurvivors -gt 0) { $continueSkip = "$mainSurvivors process(es) survived the kill" }
3057|        else {
3058|            # (wave 24b, F08-2) ONE tree check for every engine: the working tree, the brief or an
3059|            # artifact changed while the killed turn ran - codex: the fingerprints taken around the
3060|            # run (a workspace-write run may have written); an engine: its tree check, which covers
3061|            # the collab directory too. A continuation would answer about another state.
